/**
 * More English Topics, Units 15 and 16: the high school standards of the US Common Core that the
 * graded courses do not teach. Unit 15 covers seminar discussions (SL.9-10.1, SL.11-12.1), digital
 * writing and media (W.9-10.6, W.11-12.6, SL.9-10.5, SL.11-12.5), how writers transform their
 * sources (RL.9-10.9) and world literature (RL.9-10.6). Unit 16 covers a subject in two mediums and
 * productions of a play (RL.9-10.7, RL.11-12.7), the periods of American literature (RL.11-12.9),
 * the founding documents (RI.11-12.9) and the reasoning of The Federalist and the Supreme Court
 * (RI.11-12.8).
 *
 * Quotations are from texts in the public domain, checked word for word against these editions:
 * Chekhov, "The Bet", tr. Constance Garnett, in The Schoolmistress and Other Stories (1921); Tagore,
 * "The Postmaster", in Stories from Tagore (1918); Glaspell, Trifles (1916); Paine, The American
 * Crisis, No. I (1776); Emerson, "Self-Reliance" (1841); Thoreau, Walden (1854); the Declaration of
 * Independence, the Constitution and the Bill of Rights (National Archives transcriptions); The
 * Federalist Nos. 10, 51 and 78 (Avalon Project, Yale Law School); Harlan's dissent in Plessy v.
 * Ferguson (1896) and the opinion of the Court in Brown v. Board of Education (1954). Works still
 * in copyright, such as Auden's "Musée des Beaux Arts", are described and never quoted.
 */
import { skill } from '../../helpers.ts';
import type { Rng } from '../../../rng.ts';
import type { Difficulty, SkillDef } from '../../../types.ts';
import { ask, type Q } from './bank.ts';

const by = (d: Difficulty, banks: [Q[], Q[], Q[]], hints: [string[], string[], string[]]) => (rng: Rng) => ask(rng, banks[d - 1], hints[d - 1]);
/** The usual split of a bank of six: the first four, all six, the last four. */
const split = (b: Q[]): [Q[], Q[], Q[]] => [b.slice(0, 4), b, b.slice(2)];

